              , FIRST_SETUP_TIME_UOM
              , DESCR
        FROM    TH_ENG_SETUP_MATRIX A
        WHERE   A.MASTER_ID = @v_master_id
        AND     A.PLAN_ID = @v_plan_id  + '_AMEND'
        /*
        AND     EXISTS (
                        SELECT 1
                        FROM   TH_ENG_ITEM XA
                        WHERE  XA.MASTER_ID = A.MASTER_ID
                        AND    XA.PLAN_ID = A.PLAN_ID
                        AND    XA.SETUP_GROUP_ID = A.FROM_SETUP_GROUP_ID
                       )
        AND     EXISTS (
                        SELECT 1
                        FROM   TH_ENG_ITEM XB
                        WHERE  XB.MASTER_ID = A.MASTER_ID
                        AND    XB.PLAN_ID = A.PLAN_ID
                        AND    XB.SETUP_GROUP_ID = A.TO_SETUP_GROUP_ID
                       )
        */
        
              --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

      END

      /*** FP_AMEND_NET_DEMAND 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_NET_DEMAND'
        
        DELETE FROM SY_FP_AMEND_NET_DEMAND
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null

        INSERT INTO SY_FP_AMEND_NET_DEMAND
              (
                MASTER_ID
              , PLAN_ID
              , DEMAND_ID
              , SALES_MODEL_ID
              , SHIPPING_DATE
              , DUE_DATE
              , DUE_FENCE_DATE
              , EARLY_PRODUCING_TERM
              , EARLY_PRODUCING_TERM_UOM
              , QTY
              , SPLIT_QTY
              , ORDER_TYPE
              , DEMAND_TYPE
              , PRODUCING_TYPE
              , PRIORITY_GROUP_CODE
              , PRIORITY
              , ATTRIBUTE_CHECKER_ID
              , DEMAND_GROUP_ID
              , LATE_TYPE
              , DESCRIPTION
              , MOVE_TIME_RATE
              , BUFFER_TIME_RATE
              , IS_EXCEPTION
              , MFG_WEEK
              , SOP_WEEK
              , CUSTOMER_ID
              )
        SELECT 
                A.MASTER_ID
              , @v_plan_id as PLAN_ID
              , A.DEMAND_ID
              , A.SALES_MODEL_ID
              , A.SHIPPING_DATE
              , B.DUE_DATE
              , B.DUE_FENCE_DATE
              , B.EARLY_PRODUCING_TERM
              , B.EARLY_PRODUCING_TERM_UOM
              , A.QTY
              , A.SPLIT_QTY
              , A.ORDER_TYPE
              , A.DEMAND_TYPE
              , A.PRODUCING_TYPE
              , A.PRIORITY_GROUP_CODE
              , A.PRIORITY
              , A.ATTRIBUTE_CHECKER_ID
              , A.DEMAND_GROUP_ID
              , A.LATE_TYPE
              , A.DESCR   AS DESCRIPTION
              , A.MOVE_TIME_RATE
              , A.BUFFER_TIME_RATE
              , A.IS_EXCEPTION
              , B.MFG_WEEK
              , B.SOP_WEEK
              , B.CUSTOMER_ID
        FROM    TH_ENG_NET_DEMAND A,
                TH_DPP_NET_DEMAND B
        WHERE   A.MASTER_ID = B.MASTER_ID
        --AND     A.PLAN_ID = B.PLAN_ID + '_AMEND'
        AND     A.PLAN_ID = B.PLAN_ID
        AND     A.DEMAND_ID = B.NET_DEMAND_ID
        AND     A.MASTER_ID = @v_master_id
        --AND     A.PLAN_ID = @v_plan_id + '_AMEND'
        AND     A.PLAN_ID = @v_plan_id

              --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

      END


      /*** FP_AMEND_TIMEPHASED_BOR 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_TIMEPHASED_BOR'
        
        DELETE FROM SY_FP_AMEND_TIMEPHASED_BOR
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null

        SET @v_table_name = 'TH_BUF_SCM_AMEND_TIME_BOR_A'

        DELETE FROM TH_BUF_SCM_AMEND_TIME_BOR_A
        DELETE FROM TH_BUF_SCM_AMEND_TIME_BOR_B

        ;WITH W_RES_MAP AS  
              (                           
                SELECT 
                        CAST(RESOURCE_ID AS nvarchar) AS MAIN_GROUP_ID, 
                        W_ITEM_ID, W_SITE_ID, W_ROUTE_ID, W_OPERATION_ID, 
                        RESOURCE_ID, RESOURCE_GROUP_ID, RESOURCE_MAP_LEVEL, SUB_RESOURCE_MAP_ID,
                        CAST(RESOURCE_ID AS nvarchar) AS PATH,
                        CASE WHEN SUB_RESOURCE_MAP_ID IS NULL THEN 1 ELSE 0 END AS IS_LEAF                                  
                FROM  (
                        SELECT  A.SITE_ID W_SITE_ID, A.ROUTE_ID W_ROUTE_ID, A.OPERATION_ID W_OPERATION_ID, A.ITEM_ID W_ITEM_ID, 
                                B.RESOURCE_ID, A.RESOURCE_GROUP_ID, A.RESOURCE_MAP_ID,  A.RESOURCE_MAP_LEVEL, A.SUB_RESOURCE_MAP_ID
                        FROM    TH_ENG_OP_RES_GROUP_MAP A,
                                TH_ENG_RESOURCE         B
                        WHERE   A.MASTER_ID = @v_master_id
                        AND     A.PLAN_ID = @v_plan_id  + '_AMEND'
                        AND     A.MASTER_ID = B.MASTER_ID
                        AND     A.PLAN_ID = B.PLAN_ID
                        AND     A.RESOURCE_GROUP_ID = B.RESOURCE_GROUP_ID
                      ) A
                WHERE EXISTS  (
                                SELECT *
                                FROM    TH_ENG_OP_RES_GROUP_MAP B
                                WHERE   B.MASTER_ID = @v_master_id
                                AND     B.PLAN_ID = @v_plan_id + '_AMEND'
                                AND     B.RESOURCE_MAP_LEVEL = 1
                                AND     A.W_ITEM_ID = B.ITEM_ID 
                                AND     A.RESOURCE_MAP_ID=B.RESOURCE_MAP_ID
                              )
                UNION ALL
                SELECT 
                        CAST(DBO.FN_GET_MAIN_GROUP_ID(B.W_SITE_ID, B.W_ROUTE_ID, B.W_OPERATION_ID, B.W_ITEM_ID, B.RESOURCE_MAP_ID) AS nvarchar) AS MAIN_GROUP_ID,
                        --B.RESOURCE_ID AS MAIN_GROUP_ID, 
                        B.W_ITEM_ID,  B.W_SITE_ID,      B.W_ROUTE_ID,      B.W_OPERATION_ID, 
                        B.RESOURCE_ID,  B.RESOURCE_GROUP_ID,  B.RESOURCE_MAP_LEVEL,  B.SUB_RESOURCE_MAP_ID,
                        CASE WHEN CHARINDEX( CAST(DBO.FN_GET_MAIN_GROUP_ID(B.W_SITE_ID, B.W_ROUTE_ID, B.W_OPERATION_ID, B.W_ITEM_ID, B.RESOURCE_MAP_ID) AS nvarchar), CAST(C.RESOURCE_ID + ';' + B.RESOURCE_ID AS nvarchar)) > 0 
                             THEN CAST(C.RESOURCE_ID + ';' + B.RESOURCE_ID AS nvarchar) 
                             ELSE CAST(CAST(DBO.FN_GET_MAIN_GROUP_ID(B.W_SITE_ID, B.W_ROUTE_ID, B.W_OPERATION_ID, B.W_ITEM_ID, B.RESOURCE_MAP_ID) AS nvarchar) + ';' + CAST(C.RESOURCE_ID + ';' + B.RESOURCE_ID AS nvarchar) AS nvarchar) 
                        END  AS PATH,
                        CASE WHEN B.SUB_RESOURCE_MAP_ID IS NULL THEN 1 ELSE 0 END AS IS_LEAF                                  
                FROM  (
                        SELECT  A.SITE_ID W_SITE_ID, A.ROUTE_ID W_ROUTE_ID, A.OPERATION_ID W_OPERATION_ID, A.ITEM_ID W_ITEM_ID, 
                                B.RESOURCE_ID, A.RESOURCE_GROUP_ID, A.RESOURCE_MAP_ID,  A.RESOURCE_MAP_LEVEL, A.SUB_RESOURCE_MAP_ID
                        FROM    TH_ENG_OP_RES_GROUP_MAP A,
                                TH_ENG_RESOURCE         B
                        WHERE   A.MASTER_ID = @v_master_id
                        AND     A.PLAN_ID = @v_plan_id + '_AMEND'
                        AND     A.MASTER_ID = B.MASTER_ID
                        AND     A.PLAN_ID = B.PLAN_ID
                        AND     A.RESOURCE_GROUP_ID = B.RESOURCE_GROUP_ID
                      ) B
                      INNER JOIN W_RES_MAP C 
                            ON  B.W_SITE_ID               = C.W_SITE_ID
                            AND B.W_ROUTE_ID              = C.W_ROUTE_ID
                            AND B.W_OPERATION_ID          = C.W_OPERATION_ID
                            AND B.W_ITEM_ID               = C.W_ITEM_ID
                            AND B.RESOURCE_MAP_ID         = C.SUB_RESOURCE_MAP_ID                                                                               
              )
        INSERT INTO TH_BUF_SCM_AMEND_TIME_BOR_A
        SELECT * FROM W_RES_MAP

              --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

              
        SET @v_table_name = 'TH_BUF_SCM_AMEND_TIME_BOR_B'

        INSERT INTO TH_BUF_SCM_AMEND_TIME_BOR_B
        SELECT 
                --LEAD(START_TIME,1) OVER(PARTITION BY MAIN_GROUP_ID ORDER BY START_TIME) END_TIME
                A.MAIN_GROUP_ID, A.START_TIME,
                ROW_NUMBER() OVER (PARTITION BY MAIN_GROUP_ID ORDER BY START_TIME) RN,
                (ROW_NUMBER() OVER (PARTITION BY MAIN_GROUP_ID ORDER BY START_TIME))/2 RNDIV2,
                (ROW_NUMBER() OVER (PARTITION BY MAIN_GROUP_ID ORDER BY START_TIME) + 1)/2 RNPLUS1DIV2
        FROM   (
                SELECT  DISTINCT
                        A.MAIN_GROUP_ID, B.START_TIME
                FROM    TH_BUF_SCM_AMEND_TIME_BOR_A A,
                      (
                        SELECT  DISTINCT RESOURCE_ID, START_TIME
                        FROM   (
                                --RESOURCE 시작시간
                                SELECT A.RESOURCE_ID, PLAN_START_DTTM AS START_TIME
                                FROM   TH_ENG_RESOURCE  A,
                                       TH_ENG_PLAN_INFO B
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                AND    A.MASTER_ID = B.MASTER_ID
                                AND    A.PLAN_ID = B.PLAN_ID
                                UNION  ALL
                                -- RESOURCE 종료시간
                                SELECT A.RESOURCE_ID, DATEADD(DAY, PLAN_HORIZON, PLAN_START_DTTM) AS START_TIME
                                FROM   TH_ENG_RESOURCE  A,
                                       TH_ENG_PLAN_INFO B 
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                AND    A.MASTER_ID = B.MASTER_ID
                                AND    A.PLAN_ID = B.PLAN_ID
                                UNION  ALL
                                -- RESOURCE CAL 시작시간
                                SELECT A.RESOURCE_ID, A.START_DTTM AS START_TIME
                                FROM   TH_ENG_RESOURCE_CAL A
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                UNION  ALL
                                -- RESOURCE CAL 종료시간
                                SELECT A.RESOURCE_ID, A.END_DTTM AS START_TIME
                                FROM   TH_ENG_RESOURCE_CAL A
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                UNION  ALL
                                -- OP_RES_GROUP_MAP_CAL 의 시작시간
                                SELECT B.RESOURCE_ID, A.START_DTTM AS START_TIME
                                FROM   TH_ENG_OP_RES_GROUP_MAP_CAL  A,
                                       TH_ENG_RESOURCE              B
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                AND    A.MASTER_ID = B.MASTER_ID
                                AND    A.PLAN_ID = B.PLAN_ID
                                AND    A.RESOURCE_GROUP_ID = B.RESOURCE_GROUP_ID
                                UNION  ALL
                                -- OP_RES_GROUP_MAP_CAL 의 종료시간
                                SELECT B.RESOURCE_ID, A.END_DTTM AS START_TIME
                                FROM   TH_ENG_OP_RES_GROUP_MAP_CAL  A,
                                       TH_ENG_RESOURCE              B
                                WHERE  A.MASTER_ID = @v_master_id
                                AND    A.PLAN_ID = @v_plan_id + '_AMEND'
                                AND    A.MASTER_ID = B.MASTER_ID
                                AND    A.PLAN_ID = B.PLAN_ID
                                AND    A.RESOURCE_GROUP_ID = B.RESOURCE_GROUP_ID
                               ) A
                       ) B
                WHERE  1=1
                AND    A.RESOURCE_ID = B.RESOURCE_ID
                ) A
        WHERE  1=1

              --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

                
        SET @v_table_name = 'FP_AMEND_TIMEPHASED_BOR'

        INSERT INTO SY_FP_AMEND_TIMEPHASED_BOR (
                    MASTER_ID
                  , PLAN_ID
                  , COMBINE_ID
                  , SITE_ID
                  , ROUTE_ID
                  , OPERATION_ID
                  , ITEM_ID
                  , RESOURCE_ID
                  , START_TIME
                  , END_TIME
                  , UTILIZATION
                  , TACT_TIME
                  , TACT_TIME_UOM
                  , MULTI_PORT_COUNT
                  , ALT_PRIORITY
                  , YIELD
                  , RES_IS_USE
                  , TACT_IS_USE
                  )
        SELECT  DISTINCT @v_master_id, @v_plan_id, 
                --ROUTE_ID AS COMBINE_ID,         -- RESOURCE 설정부분
                COMBINE_ID,                     -- RESOURCE 설정부분
                SITE_ID, 
                ROUTE_ID, 
                OPERATION_ID, 
                ITEM_ID, 
                --ROUTE_ID AS RESOURCE_ID,        -- RESOURCE 설정부분
                RESOURCE_ID,                    -- RESOURCE 설정부분
                START_TIME, 
                END_TIME, 
                UTIL, 
                TACT_TIME, 
                TACT_TIME_UOM, 
                MULTI_PORT_COUNT, 
                ALT_PRIORITY, 
                CASE WHEN YIELD IS NULL THEN 1
                     WHEN YIELD = 0     THEN 1
                     ELSE YIELD
                END  YIELD, 
                RES_IS_USE, 
                TACT_IS_USE
        FROM   (
                SELECT  A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ITEM_ID, A.RESOURCE_ID, A.START_TIME, A.END_TIME, 
                        B.UTILIZATION UTIL_CAL, B.MULTI_PORT_COUNT MULTI_PORT_CAL, ISNULL(B.IS_USE,'Y') RES_IS_USE, 
                        ISNULL(C.IS_USE,'Y') TACT_IS_USE,
                        D.PATH AS COMBINE_ID,
                        A.UTILIZATION,
                        ISNULL(B.UTILIZATION, A.UTILIZATION) UTIL,
                        ISNULL(B.MULTI_PORT_COUNT, A.MULTI_PORT_COUNT) MULTI_PORT_COUNT,
                        ISNULL(C.TACT_TIME, A.TACT_TIME) TACT_TIME,
                        ISNULL(C.TACT_TIME_UOM, A.TACT_TIME_UOM) TACT_TIME_UOM,
                        ISNULL(ISNULL(C.ALT_PRIORITY, A.ALT_PRIORITY), 99) ALT_PRIORITY,
                        CASE WHEN C.YIELD IS NULL THEN A.YIELD
                             ELSE C.YIELD
                        END  AS YIELD
                FROM   (        
                        SELECT A.*, B.START_TIME, END_TIME
                        FROM   (   
                                SELECT  A.*,  
                                        C.SITE_ID, C.ROUTE_ID, C.OPERATION_ID, C.ITEM_ID,
                                        B.MULTI_PORT_COUNT, B.UTILIZATION,
                                        C.ALT_PRIORITY, C.TACT_TIME, C.TACT_TIME_UOM, C.YIELD 
                                FROM    TH_BUF_SCM_AMEND_TIME_BOR_A A
                                        INNER JOIN TH_ENG_RESOURCE B
                                              ON      B.MASTER_ID = @v_master_id
                                              AND     B.PLAN_ID = @v_plan_id + '_AMEND'
                                              AND     A.RESOURCE_ID = B.RESOURCE_ID
                                        INNER JOIN TH_ENG_OP_RES_GROUP_MAP C
                                              ON      C.MASTER_ID = @v_master_id
                                              AND     C.PLAN_ID = @v_plan_id + '_AMEND'
                                              AND     A.W_ITEM_ID = C.ITEM_ID
                                              AND     A.W_OPERATION_ID = C.OPERATION_ID
                                              AND     A.RESOURCE_GROUP_ID = C.RESOURCE_GROUP_ID
                               ) A,
                               (
                                SELECT  A.MAIN_GROUP_ID, A.START_TIME, A.END_TIME
                                FROM   (
                                        SELECT  RN
                                               ,RNDIV2
                                               ,RNPLUS1DIV2,
                                                MAIN_GROUP_ID, START_TIME,
                                                CASE WHEN RN%2=1 THEN MAX(CASE WHEN RN%2=0 THEN START_TIME END) OVER (PARTITION BY MAIN_GROUP_ID,RNPLUS1DIV2) 
                                                                 ELSE MAX(CASE WHEN RN%2=1 THEN START_TIME END) OVER (PARTITION BY MAIN_GROUP_ID,RNDIV2)
                                                END  AS END_TIME
                                        FROM TH_BUF_SCM_AMEND_TIME_BOR_B
                                ) A
                                WHERE 1=1
                                AND A.START_TIME < ISNULL(A.END_TIME, A.START_TIME)
                                ) B
                        WHERE  1=1
                        AND    A.MAIN_GROUP_ID = B.MAIN_GROUP_ID               
                        --ORDER  BY A.MAIN_GROUP_ID, A.ITEM_ID, B.START_TIME               
                        ) A
                        LEFT OUTER JOIN (     
                                          SELECT * 
                                          FROM   TH_ENG_RESOURCE_CAL
                                          WHERE  MASTER_ID = @v_master_id 
                                          AND    PLAN_ID = @v_plan_id + '_AMEND'
                                        ) B 
                              ON  A.RESOURCE_ID = B.RESOURCE_ID 
                              AND A.START_TIME >= B.START_DTTM 
                              AND A.END_TIME <= B.END_DTTM
                        LEFT OUTER JOIN ( 
                                          SELECT * 
                                          FROM   TH_ENG_OP_RES_GROUP_MAP_CAL
                                          WHERE  MASTER_ID = @v_master_id 
                                          AND    PLAN_ID = @v_plan_id + '_AMEND'
                                        ) C 
                              ON  A.SITE_ID = C.SITE_ID 
                              AND A.ROUTE_ID = C.ROUTE_ID 
                              AND A.OPERATION_ID = C.OPERATION_ID 
                              AND A.ITEM_ID = C.ITEM_ID  
                              AND A.RESOURCE_GROUP_ID = C.RESOURCE_GROUP_ID 
                              AND A.START_TIME >= C.START_DTTM 
                              AND A.END_TIME <= C.END_DTTM
                        INNER JOIN ( 
                                    SELECT * 
                                    FROM   TH_BUF_SCM_AMEND_TIME_BOR_A
                                    WHERE  IS_LEAF > 0
                                   ) D 
                              ON  D.W_ITEM_ID = A.ITEM_ID 
                              AND D.W_SITE_ID = A.SITE_ID 
                              AND D.W_ROUTE_ID = A.ROUTE_ID 
                              AND D.W_OPERATION_ID = A.OPERATION_ID 
                              AND D.MAIN_GROUP_ID = A.MAIN_GROUP_ID 
                              AND D.PATH LIKE A.PATH + '%'                       
                WHERE  1=1
          ) A

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

      END



      /*** FP_AMEND_TIMEPHASED_LANE_BOR 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_TIMEPHASED_LANE_BOR'
        
        DELETE FROM SY_FP_AMEND_TIMEPHASED_LANE_BOR
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null


        INSERT INTO SY_FP_AMEND_TIMEPHASED_LANE_BOR (
                    MASTER_ID
                  , PLAN_ID
                  , COMBINE_ID
                  , SITE_ID
                  , ROUTE_ID
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_TACT_QTY
                  , RESOURCE_ID
                  , START_TIME
                  , END_TIME
                  , UTILIZATION
                  , TACT_TIME
                  , TACT_TIME_UOM
                  , MULTI_PORT_COUNT
                  , ALT_PRIORITY
                  , YIELD
                  , RES_IS_USE
                  , TACT_IS_USE
                  )
        SELECT DISTINCT
                A.MASTER_ID
              , A.PLAN_ID
              , A.COMBINE_ID
              , A.SITE_ID
              , A.ROUTE_ID
              , A.OPERATION_ID
              , A.ITEM_ID
              , ISNULL(B.LANE_TACT_QTY, 0)            AS LANE_TACT_QTY
              , A.RESOURCE_ID
              , A.START_TIME
              , A.END_TIME
              , A.UTILIZATION
              , ISNULL(B.LANE_TACT_TIME, A.TACT_TIME) AS TACT_TIME
              , A.TACT_TIME_UOM
              , A.MULTI_PORT_COUNT
              , A.ALT_PRIORITY
              , A.YIELD
              , A.RES_IS_USE
              , A.TACT_IS_USE
        FROM   SY_FP_AMEND_TIMEPHASED_BOR A
               LEFT OUTER JOIN TH_MST_ITEM_LANE B
                    ON    A.MASTER_ID     = B.MASTER_ID
                    AND   A.PLAN_ID       = B.PLAN_ID
                    AND   A.ITEM_ID       = B.ITEM_ID
                    AND   A.SITE_ID       = B.FACTORY_ID
                    AND   A.ROUTE_ID      = B.LINE_ID
                    AND   A.OPERATION_ID  = B.OPERATION_ID
        WHERE  A.MASTER_ID = @v_master_id
        AND    A.PLAN_ID = @v_plan_id
        AND    A.OPERATION_ID NOT IN ('E2000','S2000')


        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        INSERT INTO SY_FP_AMEND_TIMEPHASED_LANE_BOR (
                    MASTER_ID
                  , PLAN_ID
                  , COMBINE_ID
                  , SITE_ID
                  , ROUTE_ID
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_TACT_QTY
                  , RESOURCE_ID
                  , START_TIME
                  , END_TIME
                  , UTILIZATION
                  , TACT_TIME
                  , TACT_TIME_UOM
                  , MULTI_PORT_COUNT
                  , ALT_PRIORITY
                  , YIELD
                  , RES_IS_USE
                  , TACT_IS_USE
                  )
        SELECT DISTINCT
               A.MASTER_ID
             , A.PLAN_ID
             , A.COMBINE_ID
             , A.SITE_ID
             , A.ROUTE_ID
             , A.OPERATION_ID
             , A.ITEM_ID
             , ISNULL(B.LANE_TACT_QTY, 0)            AS LANE_TACT_QTY
             , A.RESOURCE_ID
             , C.START_TIME
             , C.END_TIME
             , A.UTILIZATION
             , ISNULL(B.LANE_TACT_TIME, A.TACT_TIME) AS TACT_TIME
             , A.TACT_TIME_UOM
             , A.MULTI_PORT_COUNT
             , A.ALT_PRIORITY
             , A.YIELD
             , A.RES_IS_USE
             , A.TACT_IS_USE
        FROM   SY_FP_AMEND_TIMEPHASED_BOR A
               LEFT OUTER JOIN TH_MST_ITEM_LANE B
                    ON    A.MASTER_ID     = B.MASTER_ID
                    AND   A.PLAN_ID       = B.PLAN_ID
                    AND   A.ITEM_ID       = B.ITEM_ID
                    AND   A.SITE_ID       = B.FACTORY_ID
                    AND   A.ROUTE_ID      = B.LINE_ID
                    AND   A.OPERATION_ID  = B.OPERATION_ID
             , (
                SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, START_TIME
                     , LEAD(START_TIME, 1, NULL) OVER ( PARTITION BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID
                                                        ORDER     BY START_TIME ) AS END_TIME
                FROM   (
                        SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, START_TIME
                        FROM   (
                                SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID
                                     , OPERATION_ID
                                     , START_TIME
                                FROM   SY_FP_AMEND_TIMEPHASED_BOR A
                                WHERE  A.MASTER_ID    = @v_master_id
                                AND    A.PLAN_ID      = @v_plan_id
                                AND    A.OPERATION_ID IN ('E2000','S2000')
                                GROUP  BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, START_TIME
                                UNION  ALL
                                SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID 
                                     , CASE OPERATION_ID WHEN 'E1000' THEN 'E2000'
                                                         WHEN 'S1000' THEN 'S2000'
                                       END  AS OPERATION_ID
                                     , START_TIME
                                FROM   SY_FP_AMEND_TIMEPHASED_BOR A
                                WHERE  A.MASTER_ID    = @v_master_id
                                AND    A.PLAN_ID      = @v_plan_id
                                AND    A.OPERATION_ID IN ('E1000','S1000')
                                GROUP  BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, START_TIME
                                UNION  ALL
                                SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID
                                     , OPERATION_ID
                                     , END_TIME AS START_TIME
                                FROM   SY_FP_AMEND_TIMEPHASED_BOR A
                                WHERE  A.MASTER_ID    = @v_master_id
                                AND    A.PLAN_ID      = @v_plan_id
                                AND    A.OPERATION_ID IN ('E2000','S2000')
                                GROUP  BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, END_TIME
                                UNION  ALL
                                SELECT MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID 
                                     , CASE OPERATION_ID WHEN 'E1000' THEN 'E2000'
                                                         WHEN 'S1000' THEN 'S2000'
                                       END  AS OPERATION_ID
                                     , END_TIME AS START_TIME
                                FROM   SY_FP_AMEND_TIMEPHASED_BOR A
                                WHERE  A.MASTER_ID    = @v_master_id
                                AND    A.PLAN_ID      = @v_plan_id
                                AND    A.OPERATION_ID IN ('E1000','S1000')
                                GROUP  BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, END_TIME        
                               ) A
                        GROUP  BY MASTER_ID, PLAN_ID, SITE_ID, ROUTE_ID, OPERATION_ID, START_TIME
                       ) A
               ) C
        WHERE  C.END_TIME     IS NOT NULL
        AND    A.MASTER_ID    = @v_master_id
        AND    A.PLAN_ID      = @v_plan_id
        AND    A.OPERATION_ID IN ('E2000','S2000')
        AND    A.SITE_ID      = C.SITE_ID
        AND    A.ROUTE_ID     = C.ROUTE_ID
        AND    A.OPERATION_ID = C.OPERATION_ID
        AND    A.START_TIME  <= C.START_TIME
        AND    A.END_TIME    >= C.END_TIME

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        UPDATE SY_FP_AMEND_TIMEPHASED_LANE_BOR
        SET    SY_FP_AMEND_TIMEPHASED_LANE_BOR.TACT_TIME = B.LANE_TACT_TIME
        FROM   SY_FP_AMEND_TIMEPHASED_LANE_BOR A
               INNER JOIN TH_MST_ITEM_LANE_CAL B
                    ON    A.MASTER_ID     = B.MASTER_ID
                    AND   A.PLAN_ID       = B.PLAN_ID
                    AND   A.ITEM_ID       = B.ITEM_ID
                    AND   A.LANE_TACT_QTY = B.LANE_TACT_QTY
                    AND   A.SITE_ID       = B.FACTORY_ID
                    AND   A.ROUTE_ID      = B.LINE_ID
                    AND   A.OPERATION_ID  = B.OPERATION_ID
                    AND   A.START_TIME   <= B.START_TIME
                    AND   A.END_TIME     >= B.END_TIME
        WHERE  A.MASTER_ID  = @v_master_id
        AND    A.PLAN_ID    = @v_plan_id

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        -- 2017.06.20 : 전극 전공정 대상이며, CHILD 에 SLURRY-BATCH 가 없을 경우 표시하도록 설정함
        IF    CHARINDEX('E_PRE', @v_master_id) > 0
          OR  CHARINDEX('SRS',   @v_master_id) > 0
          BEGIN
          
            UPDATE SY_FP_AMEND_TIMEPHASED_LANE_BOR
            SET    SY_FP_AMEND_TIMEPHASED_LANE_BOR.SUB_BATCH_FLAG = 'N'
            FROM   SY_FP_AMEND_TIMEPHASED_LANE_BOR A,
                   (
                    SELECT *
                    FROM   (
                            SELECT DISTINCT
                                   A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID, B.BATCH_GROUP_ID
                                 , MAX(B.BATCH_GROUP_ID) OVER (PARTITION BY A.PARENT_ITEM_ID, A.SITE_ID, A.ALT_ID, A.BOM_VERSION_ID) AS BATCH_ID
                            FROM   (
                                    SELECT DISTINCT
                                           A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID, B.OPERATION_ID CHILD_OPERATION_ID
                                    FROM   (
                                            SELECT DISTINCT
                                                   A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID
                                            FROM   TH_ENG_PLAN_BOM  A
                                            WHERE  A.MASTER_ID  = @v_master_id
                                            AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                            AND    A.OPERATION_ID IN ('E2000','S2000')
                                           ) A,
                                           (
                                            SELECT A.ITEM_ID, A.OPERATION_ID
                                            FROM   TH_ENG_ITEM_ROUTE_SITE A
                                            WHERE  A.MASTER_ID  = @v_master_id
                                            AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                            AND    EXISTS (
                                                            SELECT 1
                                                            FROM   (
                                                                    SELECT DISTINCT 
                                                                           A.OPERATION_ID
                                                                    FROM   SY_SCM_OPERATION_M A,
                                                                           SY_SCM_FACTORY_M B,
                                                                           SY_FP_INSTANCE_FACTORY_M C
                                                                    WHERE  A.COMPANY_ID   = B.COMPANY_ID
                                                                    AND    A.DIVISION_ID  = B.DIVISION_ID
                                                                    AND    A.SITE_ID      = B.SITE_ID
                                                                    AND    A.ACTIVE_FLAG  = 'Y'
                                                                    AND    A.CAPA_TYPE    = 'BATCH'
                                                                    AND    B.FACTORY_ID   = C.FACTORY_ID
                                                                    AND    C.INSTANCE_ID  = @v_master_id
                                                                   ) X
                                                            WHERE  A.OPERATION_ID = X.OPERATION_ID
                                                          )
                                            GROUP  BY A.ITEM_ID, A.OPERATION_ID
                                           ) B
                                    WHERE  A.CHILD_ITEM_ID = B.ITEM_ID
                                   ) A
                                   LEFT OUTER JOIN TH_ENG_BATCH_INFO B
                                        ON    B.MASTER_ID = @v_master_id
                                        AND   B.PLAN_ID   = @v_plan_id   + '_AMEND'
                                        AND   A.CHILD_ITEM_ID = B.ITEM_ID
                                        AND   A.SITE_ID = B.DESCR
                            WHERE  1=1
                           ) A
                    WHERE  BATCH_ID IS NULL
                   ) B
            WHERE  A.MASTER_ID    = @v_master_id
            AND    A.PLAN_ID      = @v_plan_id
            AND    A.ITEM_ID      = B.PARENT_ITEM_ID
            AND    A.SITE_ID      = B.SITE_ID
            AND    A.OPERATION_ID = B.OPERATION_ID

            SET @v_message = 'SUB_BATCH_FLAG - FACTORY  : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
            SET @n_log_count = @n_log_count + 1
            SET @sysdate = GETDATE()
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
            
            UPDATE SY_FP_AMEND_TIMEPHASED_LANE_BOR
            SET    SY_FP_AMEND_TIMEPHASED_LANE_BOR.SUB_BATCH_FLAG = 'N'
            FROM   SY_FP_AMEND_TIMEPHASED_LANE_BOR A,
                   (
                    SELECT *
                    FROM   (
                            SELECT DISTINCT
                                   A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID
                                 , MAX(B.ITEM_ID) OVER (PARTITION BY A.PARENT_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.ALT_ID, A.BOM_VERSION_ID) AS BATCH_ID
                            FROM   (
                                    SELECT DISTINCT
                                           A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID, B.OPERATION_ID CHILD_OPERATION_ID
                                    FROM   (
                                            SELECT DISTINCT
                                                   A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID
                                            FROM   TH_ENG_PLAN_BOM  A
                                            WHERE  A.MASTER_ID  = @v_master_id
                                            AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                            AND    A.OPERATION_ID IN ('E2000','S2000')
                                           ) A,
                                           (
                                            SELECT A.ITEM_ID, A.OPERATION_ID
                                            FROM   TH_ENG_ITEM_ROUTE_SITE A
                                            WHERE  A.MASTER_ID  = @v_master_id
                                            AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                            AND    EXISTS (
                                                            SELECT 1
                                                            FROM   (
                                                                    SELECT DISTINCT 
                                                                           A.OPERATION_ID
                                                                    FROM   SY_SCM_OPERATION_M A,
                                                                           SY_SCM_FACTORY_M B,
                                                                           SY_FP_INSTANCE_FACTORY_M C
                                                                    WHERE  A.COMPANY_ID   = B.COMPANY_ID
                                                                    AND    A.DIVISION_ID  = B.DIVISION_ID
                                                                    AND    A.SITE_ID      = B.SITE_ID
                                                                    AND    A.ACTIVE_FLAG  = 'Y'
                                                                    AND    A.CAPA_TYPE    = 'BATCH'
                                                                    AND    B.FACTORY_ID   = C.FACTORY_ID
                                                                    AND    C.INSTANCE_ID  = @v_master_id
                                                                   ) X
                                                            WHERE  A.OPERATION_ID = X.OPERATION_ID
                                                          )
                                            GROUP  BY A.ITEM_ID, A.OPERATION_ID
                                           ) B
                                    WHERE  A.CHILD_ITEM_ID = B.ITEM_ID
                                   ) A
                                   LEFT OUTER JOIN TH_ENG_OP_RES_GROUP_MAP B
                                        ON    B.MASTER_ID     = @v_master_id
                                        AND   B.PLAN_ID       = @v_plan_id   + '_AMEND'
                                        AND   B.ITEM_ID       = A.CHILD_ITEM_ID
                                        AND   B.SITE_ID       = A.SITE_ID
                                        AND   B.ROUTE_ID      = A.ROUTE_ID
                                        AND   B.OPERATION_ID  = A.CHILD_OPERATION_ID
                           ) A
                    WHERE  BATCH_ID IS NULL
                   ) B
            WHERE  A.MASTER_ID    = @v_master_id
            AND    A.PLAN_ID      = @v_plan_id
            AND    A.ITEM_ID      = B.PARENT_ITEM_ID
            AND    A.SITE_ID      = B.SITE_ID
            AND    A.ROUTE_ID     = B.ROUTE_ID
            AND    A.OPERATION_ID = B.OPERATION_ID
            AND    A.SUB_BATCH_FLAG = 'Y'
            
            SET @v_message = 'SUB_BATCH_FLAG - LINE     : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
            SET @n_log_count = @n_log_count + 1
            SET @sysdate = GETDATE()
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

            UPDATE SY_FP_AMEND_TIMEPHASED_LANE_BOR
            SET    SY_FP_AMEND_TIMEPHASED_LANE_BOR.SUB_BATCH_FLAG = 'N'
            FROM   SY_FP_AMEND_TIMEPHASED_LANE_BOR A
                   LEFT OUTER JOIN (
                                    SELECT B.*, A.START_TIME, A.END_TIME, A.TACT_IS_USE
                                    FROM   SY_FP_AMEND_TIMEPHASED_LANE_BOR A,
                                           (
                                            SELECT DISTINCT
                                                   A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID, B.OPERATION_ID CHILD_OPERATION_ID
                                            FROM   (
                                                    SELECT DISTINCT
                                                           A.PARENT_ITEM_ID, A.CHILD_ITEM_ID, A.SITE_ID, A.ROUTE_ID, A.OPERATION_ID, A.ALT_ID, A.BOM_VERSION_ID
                                                    FROM   TH_ENG_PLAN_BOM  A
                                                    WHERE  A.MASTER_ID  = @v_master_id
                                                    AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                                    AND    A.OPERATION_ID IN ('E2000','S2000')
                                                   ) A,
                                                   (
                                                    SELECT A.ITEM_ID, A.OPERATION_ID
                                                    FROM   TH_ENG_ITEM_ROUTE_SITE A
                                                    WHERE  A.MASTER_ID  = @v_master_id
                                                    AND    A.PLAN_ID    = @v_plan_id   + '_AMEND'
                                                    AND    EXISTS (
                                                                    SELECT 1
                                                                    FROM   (
                                                                            SELECT DISTINCT 
                                                                                   A.OPERATION_ID
                                                                            FROM   SY_SCM_OPERATION_M A,
                                                                                   SY_SCM_FACTORY_M B,
                                                                                   SY_FP_INSTANCE_FACTORY_M C
                                                                            WHERE  A.COMPANY_ID   = B.COMPANY_ID
                                                                            AND    A.DIVISION_ID  = B.DIVISION_ID
                                                                            AND    A.SITE_ID      = B.SITE_ID
                                                                            AND    A.ACTIVE_FLAG  = 'Y'
                                                                            AND    A.CAPA_TYPE    = 'BATCH'
                                                                            AND    B.FACTORY_ID   = C.FACTORY_ID
                                                                            AND    C.INSTANCE_ID  = @v_master_id
                                                                           ) X
                                                                    WHERE  A.OPERATION_ID = X.OPERATION_ID
                                                                  )
                                                    GROUP  BY A.ITEM_ID, A.OPERATION_ID
                                                   ) B
                                            WHERE  A.CHILD_ITEM_ID = B.ITEM_ID
                                           ) B
                                    WHERE  A.MASTER_ID    = @v_master_id
                                    AND    A.PLAN_ID      = @v_plan_id
                                    AND    A.ITEM_ID      = B.CHILD_ITEM_ID
                                    AND    A.SITE_ID      = B.SITE_ID
                                    AND    A.ROUTE_ID     = B.ROUTE_ID
                                    AND    A.OPERATION_ID = B.CHILD_OPERATION_ID
                                    AND    A.TACT_IS_USE  = 'Y'
                                    AND    A.RES_IS_USE   = 'Y'
                                   ) B
                   ON   1=1  
                   AND  A.ITEM_ID      = B.PARENT_ITEM_ID
                   AND  A.SITE_ID      = B.SITE_ID
                   AND  A.ROUTE_ID     = B.ROUTE_ID
                   AND  A.OPERATION_ID = B.OPERATION_ID
                   AND  A.START_TIME   >= B.START_TIME
                   AND  A.END_TIME     <= B.END_TIME
            WHERE  A.MASTER_ID    = @v_master_id
            AND    A.PLAN_ID      = @v_plan_id
            AND    A.OPERATION_ID IN ('E2000','S2000')
            AND    A.SUB_BATCH_FLAG = 'Y'
            AND    B.TACT_IS_USE  IS NULL
              
            SET @v_message = 'SUB_BATCH_FLAG - CALENDAR : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
            SET @n_log_count = @n_log_count + 1
            SET @sysdate = GETDATE()
            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

          END
      END

      ----------------------------------------------------------------------------------------------------------
      ----------------------------------------------------------------------------------------------------------
      -- 결과들
      ----------------------------------------------------------------------------------------------------------
      ----------------------------------------------------------------------------------------------------------

      /*** FP_AMEND_WORK_ORDER_SPL 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_WORK_ORDER_SPL'
        
        DELETE FROM SY_FP_AMEND_WORK_ORDER_SPL
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null

        SET @v_table_name = 'TH_BUF_SCM_AMEND_WORK_ORDER_SPL'

        DELETE FROM TH_BUF_SCM_AMEND_WORK_ORDER_SPL
        
        INSERT INTO TH_BUF_SCM_AMEND_WORK_ORDER_SPL
        SELECT  DISTINCT
                A.MASTER_ID, 
                @v_plan_id as PLAN_ID, 
                A.OUT_VERSION_ID, 
                A.WORK_ORDER_ID,
                'N' MOVE_FLAG, 
                --A.ROUTE_ID AS RESOURCE_ID,            -- RESOURCE 설정부분
                A.RESOURCE_ID,                        -- RESOURCE 설정부분
                A.ITEM_ID, 
                A.SITE_ID, 
                A.ROUTE_ID, 
                A.OPERATION_ID, 
                A.START_TIME, 
                A.END_TIME, 
                A.OPERATION_TIME, 
                A.TOTAL_WORKING_TIME, 
                A.OPERATION_QTY, 
                A.COMPLETE_QTY, 
                A.BATCH_QTY,
                A.WORK_ORDER_ID AS ORG_WORK_ORDER_ID,
                CASE WHEN C.WORK_ORDER_ID IS NULL THEN 'N' ELSE 'Y' END AS IS_FIXED,
                NULL SETUP_GROUP_ID,
                NULL SUB_RESOURCE_ID
        FROM    TH_BUF_OUT_WORK_ORDER A 
          LEFT OUTER JOIN TH_ENG_FIXED_PLAN C 
                ON A.MASTER_ID = C.MASTER_ID AND A.PLAN_ID = C.PLAN_ID AND A.WORK_ORDER_ID = C.WORK_ORDER_ID
          INNER JOIN TH_ENG_RESOURCE E 
                ON A.MASTER_ID = E.MASTER_ID AND A.PLAN_ID = E.PLAN_ID AND A.RESOURCE_ID = E.RESOURCE_ID
        WHERE   A.MASTER_ID  = @v_master_id  
        AND     A.PLAN_ID     = @v_plan_id
        AND     A.OUT_VERSION_ID  = @v_out_version_id
        AND     E.RESOURCE_TYPE = 'MAIN'

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        UPDATE TH_BUF_SCM_AMEND_WORK_ORDER_SPL
        SET    TH_BUF_SCM_AMEND_WORK_ORDER_SPL.SETUP_GROUP_ID = D.SETUP_GROUP_ID
        FROM   TH_BUF_SCM_AMEND_WORK_ORDER_SPL A,
               TH_ENG_ITEM D
        WHERE  A.MASTER_ID  = @v_master_id  
        AND    A.PLAN_ID     = @v_plan_id
        AND    A.OUT_VERSION_ID  = @v_out_version_id
        AND    A.MASTER_ID = D.MASTER_ID 
        AND    A.PLAN_ID + '_AMEND' = D.PLAN_ID 
        AND    A.ITEM_ID = D.ITEM_ID
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        /*
        UPDATE TH_BUF_SCM_AMEND_WORK_ORDER_SPL
        SET    TH_BUF_SCM_AMEND_WORK_ORDER_SPL.SUB_RESOURCE_ID = F.SUB_RESOURCE_ID
        FROM   TH_BUF_SCM_AMEND_WORK_ORDER_SPL A,
               TH_BUF_OUT_ORDER_TRACKING F
        WHERE  A.MASTER_ID  = @v_master_id  
        AND    A.PLAN_ID     = @v_plan_id
        AND    A.OUT_VERSION_ID  = @v_out_version_id
        AND    A.MASTER_ID = F.MASTER_ID 
        AND    A.PLAN_ID + '_AMEND' = F.PLAN_ID 
        AND    A.OUT_VERSION_ID = F.OUT_VERSION_ID 
        AND    CHARINDEX(F.ORDER_ID,A.WORK_ORDER_ID) > 0
        */
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
        
        SET @v_table_name = 'FP_AMEND_WORK_ORDER_SPL'

        INSERT  INTO SY_FP_AMEND_WORK_ORDER_SPL ( 
              MASTER_ID, 
              PLAN_ID, 
              OUT_VERSION_ID,
              USER_ID,
              USER_EDIT_DATE, 
              WORK_ORDER_ID, 
              MOVE_FLAG,
              RESOURCE_ID, 
              ITEM_ID, 
              SITE_ID, 
              ROUTE_ID, 
              OPERATION_ID, 
              START_TIME, 
              END_TIME, 
              OPERATION_TIME, 
              TOTAL_WORKING_TIME, 
              OPERATION_QTY, 
              COMPLETE_QTY, 
              BATCH_QTY, 
              ORG_WORK_ORDER_ID, 
              ROUTE_GROUP, 
              SEQ,
              IS_FIXED, 
              IS_LOCK, 
              IS_START_LOCK,
              SETUP_GROUP_ID,
              SUB_RESOURCE_ID,
              ORG_START_TIME,
              ORG_END_TIME,
              ORG_RESOURCE_ID
        )
        SELECT  DISTINCT
                A.MASTER_ID, 
                A.PLAN_ID, 
                A.OUT_VERSION_ID, 
                '-' USER_ID,
                GETDATE() AS USER_EDIT_DATE,
                A.WORK_ORDER_ID,
                'N' MOVE_FLAG, 
                --A.ROUTE_ID AS RESOURCE_ID,            -- RESOURCE 설정부분
                A.RESOURCE_ID,                        -- RESOURCE 설정부분
                A.ITEM_ID, 
                A.SITE_ID, 
                A.ROUTE_ID, 
                A.OPERATION_ID, 
                A.START_TIME, 
                A.END_TIME, 
                A.OPERATION_TIME, 
                A.TOTAL_WORKING_TIME, 
                A.OPERATION_QTY, 
                A.COMPLETE_QTY, 
                A.BATCH_QTY, 
                A.ORG_WORK_ORDER_ID, 
                NULL ROUTE_GROUP, 
                DENSE_RANK() OVER ( PARTITION BY A.RESOURCE_ID , 
                          CASE WHEN REPLACE(CONVERT(nvarchar(8),A.START_TIME,108),':','') = B.BASIS_START_TIME THEN CONVERT(nvarchar(10),A.START_TIME,126) ELSE (CASE WHEN (CASE WHEN REPLACE(CONVERT(nvarchar(8),A.START_TIME,108),':','') > B.BASIS_START_TIME THEN REPLACE(CONVERT(nvarchar(8),A.START_TIME,108),':','') ELSE B.BASIS_START_TIME END) = B.BASIS_START_TIME THEN CONVERT(nvarchar(10),DATEADD(DAY,-1,A.START_TIME),126) ELSE CONVERT(nvarchar(10),A.START_TIME,126) END) END             
                          ORDER BY A.RESOURCE_ID , A.START_TIME )  SEQ,
                A.IS_FIXED,
                'N' IS_LOCK, 
                'N' IS_START_LOCK,
                A.SETUP_GROUP_ID,
                A.SUB_RESOURCE_ID,
                A.START_TIME ORG_START_TIME,
                A.END_TIME ORG_END_TIME,
                A.RESOURCE_ID ORG_RESOURCE_ID
        FROM    (
                  SELECT 
                         A.MASTER_ID
                       , A.PLAN_ID
                       , A.OUT_VERSION_ID
                       , ISNULL(B.WORK_ORDER_ID, A.WORK_ORDER_ID) AS WORK_ORDER_ID 
                       , A.MOVE_FLAG
                       , A.RESOURCE_ID
                       , A.ITEM_ID
                       , A.SITE_ID
                       , A.ROUTE_ID
                       , A.OPERATION_ID
                       , MIN(A.START_TIME)          AS START_TIME
                       , MIN(A.END_TIME)            AS END_TIME
                       , SUM(A.OPERATION_TIME)      AS OPERATION_TIME
                       , SUM(A.TOTAL_WORKING_TIME)  AS TOTAL_WORKING_TIME
                       , SUM(A.OPERATION_QTY)       AS OPERATION_QTY
                       , SUM(A.COMPLETE_QTY)        AS COMPLETE_QTY
                       , SUM(A.BATCH_QTY)           AS BATCH_QTY
                       , ISNULL(B.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID) AS ORG_WORK_ORDER_ID
                       , A.IS_FIXED
                       , A.SETUP_GROUP_ID
                       , A.SUB_RESOURCE_ID
                  FROM   TH_BUF_SCM_AMEND_WORK_ORDER_SPL A
                         LEFT OUTER JOIN TH_MST_SCM_FIX_WORK_SPLIT B
                              ON    A.MASTER_ID = B.MASTER_ID
                              AND   A.PLAN_ID = B.PLAN_ID
                              AND   A.WORK_ORDER_ID = B.SPLIT_WORK_ORDER_ID
                  WHERE  A.MASTER_ID = @v_master_id
                  AND    A.PLAN_ID   = @v_plan_id
                  GROUP  BY
                         A.MASTER_ID
                       , A.PLAN_ID
                       , A.OUT_VERSION_ID
                       , ISNULL(B.WORK_ORDER_ID, A.WORK_ORDER_ID)
                       , A.MOVE_FLAG
                       , A.RESOURCE_ID
                       , A.ITEM_ID
                       , A.SITE_ID
                       , A.ROUTE_ID
                       , A.OPERATION_ID
                       , ISNULL(B.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID)
                       , A.IS_FIXED
                       , A.SETUP_GROUP_ID
                       , A.SUB_RESOURCE_ID
                ) A
                INNER JOIN (
                            SELECT  MASTER_ID ,
                                    --PLAN_ID ,
                                    PLAN_TYPE ,
                                    PLAN_START_DTTM ,
                                    REPLACE(CONVERT(nvarchar(8),PLAN_START_DTTM,108),':','') BASIS_START_TIME
                            FROM    TH_ENG_PLAN_INFO
                            WHERE   MASTER_ID  = @v_master_id 
                            AND     PLAN_ID     = @v_plan_id + '_AMEND'
                          ) B 
                      ON  A.MASTER_ID = B.MASTER_ID 
                      --AND A.PLAN_ID = B.PLAN_ID
        
          
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
        
        /* PR_SCM_OF_AMEND_ADJUST 로 이관         
        UPDATE  SY_FP_AMEND_WORK_ORDER_SPL
        SET     WORK_ORDER_ID       = REPLACE(A.WORK_ORDER_ID, A.ORG_WORK_ORDER_ID, B.PLAN_ORDER_ID)
                ,ORG_WORK_ORDER_ID  =  B.PLAN_ORDER_ID
        FROM    SY_FP_AMEND_WORK_ORDER_SPL A
                ,TH_EXP_PLANORDER B 
        WHERE   A.MASTER_ID         = B.MASTER_ID 
        AND     A.PLAN_ID           = B.PLAN_ID 
        AND     A.ORG_WORK_ORDER_ID = B.ORDER_ID
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
          
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
        */
        
      END


      /*** FP_AMEND_DELIVERY_ORDER 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_DELIVERY_ORDER'
        
        DELETE FROM SY_FP_AMEND_DELIVERY_ORDER
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null

      END
      
      /*** FP_AMEND_ORDER_TRACKING 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_ORDER_TRACKING'
        
        DELETE FROM SY_FP_AMEND_ORDER_TRACKING
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null


        DELETE FROM TH_BUF_SCM_AMEND_ORDER_TRACKING_A
        
        ;WITH BALANCE_DETAILS
              AS
              (
                SELECT  DISTINCT 
                        MASTER_ID, 
                        PLAN_ID, 
                        OUT_VERSION_ID, 
                        DEMAND_ID, 
                        OPERATION_SEQ, 
                        ORDER_ID ,
                        START_TIME,
                        END_TIME
                FROM    TH_BUF_OUT_ORDER_TRACKING
                WHERE   MASTER_ID       = @v_master_id
                AND     PLAN_ID         = @v_plan_id
                AND     OUT_VERSION_ID  = @v_out_version_id 
              ),
              BALANCE_CTE 
              AS
              (
                SELECT
                      (ROW_NUMBER() OVER (PARTITION BY DEMAND_ID ORDER BY DEMAND_ID , OPERATION_SEQ)) RN,
                      (ROW_NUMBER() OVER (PARTITION BY DEMAND_ID ORDER BY DEMAND_ID , OPERATION_SEQ))/2 RNDIV2,
                      (ROW_NUMBER() OVER (PARTITION BY DEMAND_ID ORDER BY DEMAND_ID , OPERATION_SEQ) + 1)/2 RNPLUS1DIV2,
                      MASTER_ID, 
                      PLAN_ID, 
                      OUT_VERSION_ID, 
                      DEMAND_ID, 
                      OPERATION_SEQ, 
                      ORDER_ID ,
                      START_TIME,
                      END_TIME
                FROM  BALANCE_DETAILS
              )
        INSERT INTO TH_BUF_SCM_AMEND_ORDER_TRACKING_A      
        SELECT *
        FROM   (
                SELECT
                      MASTER_ID,
                      PLAN_ID,
                      OUT_VERSION_ID,
                      DEMAND_ID,
                      ORDER_ID,
                      ISNULL(
                        CAST
                        (
                          CAST( DATEDIFF(SECOND, END_TIME, (CASE WHEN RN%2=1 THEN MAX(CASE WHEN RN%2=0 THEN START_TIME END) OVER (PARTITION BY DEMAND_ID,RNPLUS1DIV2) 
                                                                             ELSE MAX(CASE WHEN RN%2=1 THEN START_TIME END) OVER (PARTITION BY DEMAND_ID,RNDIV2) END)) AS FLOAT)
                          / (60*60*24)
                        AS FLOAT
                        ) 
                      ,0) * 86400 AS WO_LT
                FROM BALANCE_CTE
           ) A
        WHERE WO_LT <> 0


        INSERT  INTO SY_FP_AMEND_ORDER_TRACKING ( 
                MASTER_ID, 
                PLAN_ID, 
                OUT_VERSION_ID, 
                DEMAND_ID, 
                TRACK_SEQ, 
                OPERATION_SEQ, 
                SITE_ID, 
                ROUTE_ID, 
                OPERATION_ID, 
                RESOURCE_ID, 
                OUT_ITEM_ID, 
                COMPLETE_QTY, 
                OUT_ITEM_PEGGING_ID, 
                IN_ITEM_ID, 
                OPERATION_QTY, 
                IN_ITEM_PEGGING_ID, 
                ORDER_ID, 
                ORDER_ID_TYPE, 
                START_TIME, 
                END_TIME, 
                LPST, 
                EPST, 
                AVAILABLE_TIME, 
                FROM_SITE_ID, 
                FROM_ROUTE_ID, 
                FROM_OPERATION_ID, 
                TO_SITE_ID, 
                TO_ROUTE_ID, 
                TO_OPERATION_ID, 
                PLAN_DESCR, 
                SUB_RESOURCE_ID, 
                LOT_ID ,
                WO_LT,
                TOP_ITEM_ID,
                PRODUCTION_TYPE
              )
        SELECT  A.MASTER_ID, 
                A.PLAN_ID, 
                A.OUT_VERSION_ID, 
                A.DEMAND_ID, 
                A.TRACK_SEQ, 
                A.OPERATION_SEQ, 
                A.SITE_ID, 
                A.ROUTE_ID, 
                A.OPERATION_ID, 
                A.RESOURCE_ID,                        -- RESOURCE 설정부분
                A.OUT_ITEM_ID, 
                A.COMPLETE_QTY, 
                A.OUT_ITEM_PEGGING_ID, 
                A.IN_ITEM_ID, 
                A.OPERATION_QTY, 
                A.IN_ITEM_PEGGING_ID, 
                ISNULL(B.WORK_ORDER_ID, A.ORDER_ID) AS ORDER_ID, 
                A.ORDER_ID_TYPE, 
                A.START_TIME, 
                A.END_TIME, 
                A.LPST, 
                A.EPST, 
                A.AVAILABLE_TIME, 
                A.FROM_SITE_ID, 
                A.FROM_ROUTE_ID, 
                A.FROM_OPERATION_ID, 
                A.TO_SITE_ID, 
                A.TO_ROUTE_ID, 
                A.TO_OPERATION_ID, 
                A.PLAN_DESCR, 
                A.SUB_RESOURCE_ID, 
                A.LOT_ID ,
                A.WO_LT,
                A.ITEM_ID,
                A.PRODUCTION_TYPE        
        FROM   (
                SELECT  A.MASTER_ID, 
                        A.PLAN_ID, 
                        A.OUT_VERSION_ID, 
                        A.DEMAND_ID, 
                        MIN(A.TRACK_SEQ) AS TRACK_SEQ, 
                        A.OPERATION_SEQ, 
                        A.SITE_ID, 
                        A.ROUTE_ID, 
                        A.OPERATION_ID, 
                        --A.ROUTE_ID AS RESOURCE_ID,            -- RESOURCE 설정부분
                        A.RESOURCE_ID,                        -- RESOURCE 설정부분
                        A.OUT_ITEM_ID, 
                        A.COMPLETE_QTY, 
                        A.OUT_ITEM_PEGGING_ID, 
                        A.IN_ITEM_ID, 
                        A.OPERATION_QTY, 
                        A.IN_ITEM_PEGGING_ID, 
                        A.ORDER_ID, 
                        A.ORDER_ID_TYPE, 
                        A.START_TIME, 
                        A.END_TIME, 
                        A.LPST, 
                        A.EPST, 
                        A.AVAILABLE_TIME, 
                        A.FROM_SITE_ID, 
                        A.FROM_ROUTE_ID, 
                        A.FROM_OPERATION_ID, 
                        A.TO_SITE_ID, 
                        A.TO_ROUTE_ID, 
                        A.TO_OPERATION_ID, 
                        A.PLAN_DESCR, 
                        A.SUB_RESOURCE_ID, 
                        A.LOT_ID ,
                        CASE WHEN MAX(B.WO_LT) IS NULL THEN 0.0 ELSE MAX(B.WO_LT) END WO_LT,
                        C.ITEM_ID,
                        C.ORDER_TYPE AS PRODUCTION_TYPE
                FROM    TH_BUF_OUT_ORDER_TRACKING A
                        LEFT  OUTER JOIN TH_BUF_SCM_AMEND_ORDER_TRACKING_A B
                              ON    A.MASTER_ID       = B.MASTER_ID 
                              AND   A.PLAN_ID         = B.PLAN_ID 
                              AND   A.OUT_VERSION_ID  = B.OUT_VERSION_ID 
                              AND   A.DEMAND_ID       = B.DEMAND_ID 
                              AND   A.ORDER_ID        = B.ORDER_ID
                        INNER  JOIN TH_DPP_NET_DEMAND C
                              ON    A.MASTER_ID = C.MASTER_ID
                              AND   A.PLAN_ID   = C.PLAN_ID
                              AND   A.DEMAND_ID = C.NET_DEMAND_ID
                WHERE   A.MASTER_ID       = @v_master_id  
                AND     A.PLAN_ID         = @v_plan_id
                AND     A.OUT_VERSION_ID  = @v_out_version_id 
                --AND     A.ORDER_ID_TYPE != 'D'    -- 이동 계획은 제외함..
                GROUP  BY 
                        A.MASTER_ID, 
                        A.PLAN_ID, 
                        A.OUT_VERSION_ID, 
                        A.DEMAND_ID, 
                        A.OPERATION_SEQ, 
                        A.SITE_ID, 
                        A.ROUTE_ID, 
                        A.OPERATION_ID, 
                        --A.ROUTE_ID AS RESOURCE_ID,            -- RESOURCE 설정부분
                        A.RESOURCE_ID,                        -- RESOURCE 설정부분
                        A.OUT_ITEM_ID, 
                        A.COMPLETE_QTY, 
                        A.OUT_ITEM_PEGGING_ID, 
                        A.IN_ITEM_ID, 
                        A.OPERATION_QTY, 
                        A.IN_ITEM_PEGGING_ID, 
                        A.ORDER_ID, 
                        A.ORDER_ID_TYPE, 
                        A.START_TIME, 
                        A.END_TIME, 
                        A.LPST, 
                        A.EPST, 
                        A.AVAILABLE_TIME, 
                        A.FROM_SITE_ID, 
                        A.FROM_ROUTE_ID, 
                        A.FROM_OPERATION_ID, 
                        A.TO_SITE_ID, 
                        A.TO_ROUTE_ID, 
                        A.TO_OPERATION_ID, 
                        A.PLAN_DESCR, 
                        A.SUB_RESOURCE_ID, 
                        A.LOT_ID ,
                        C.ITEM_ID,
                        C.ORDER_TYPE
               ) A
               LEFT OUTER JOIN TH_MST_SCM_FIX_WORK_SPLIT B
                    ON    A.MASTER_ID = B.MASTER_ID
                    AND   A.PLAN_ID   = B.PLAN_ID
                    AND   A.ORDER_ID  = B.SPLIT_WORK_ORDER_ID
        ORDER  BY DEMAND_ID , OPERATION_SEQ , TRACK_SEQ
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
        
        -- DELIVERY 계획을 끊고 WORK 와 WORK 를 연결
        UPDATE SY_FP_AMEND_ORDER_TRACKING
        SET    SY_FP_AMEND_ORDER_TRACKING.OUT_ITEM_PEGGING_ID = B.OUT_ITEM_PEGGING_ID
        FROM   SY_FP_AMEND_ORDER_TRACKING A,
               (SELECT DEMAND_ID, IN_ITEM_PEGGING_ID, OUT_ITEM_PEGGING_ID
                FROM   SY_FP_AMEND_ORDER_TRACKING
                WHERE  MASTER_ID  = @v_master_id  
                AND    PLAN_ID     = @v_plan_id
                AND    OUT_VERSION_ID  = @v_out_version_id 
                AND    ORDER_ID_TYPE = 'D'
               ) B
        WHERE  A.MASTER_ID  = @v_master_id  
        AND    A.PLAN_ID     = @v_plan_id
        AND    A.OUT_VERSION_ID  = @v_out_version_id 
        AND    A.DEMAND_ID = B.DEMAND_ID
        AND    A.ORDER_ID_TYPE = 'W'
        AND    A.OUT_ITEM_PEGGING_ID = B.IN_ITEM_PEGGING_ID
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        -- 끊긴 DELIVERY 계획 삭제
        DELETE FROM A
        FROM   SY_FP_AMEND_ORDER_TRACKING A,
               (SELECT DEMAND_ID, IN_ITEM_PEGGING_ID, OUT_ITEM_PEGGING_ID
                FROM   SY_FP_AMEND_ORDER_TRACKING
                WHERE  MASTER_ID  = @v_master_id  
                AND    PLAN_ID     = @v_plan_id
                AND    OUT_VERSION_ID  = @v_out_version_id 
                AND    ORDER_ID_TYPE = 'W'
               ) B
        WHERE  A.MASTER_ID  = @v_master_id  
        AND    A.PLAN_ID     = @v_plan_id
        AND    A.OUT_VERSION_ID  = @v_out_version_id 
        AND    A.DEMAND_ID = B.DEMAND_ID
        AND    A.ORDER_ID_TYPE = 'D'
        AND    A.OUT_ITEM_PEGGING_ID = B.OUT_ITEM_PEGGING_ID

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null
        
        /* PR_SCM_OF_AMEND_ADJUST 로 이관         
        UPDATE  SY_FP_AMEND_ORDER_TRACKING
        SET     ORDER_ID            = B.PLAN_ORDER_ID
        FROM    SY_FP_AMEND_ORDER_TRACKING A
                ,TH_EXP_PLANORDER B 
        WHERE   A.MASTER_ID         = B.MASTER_ID 
        AND     A.PLAN_ID           = B.PLAN_ID 
        AND     A.ORDER_ID          = B.ORDER_ID
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
        AND     A.OUT_VERSION_ID    = @v_out_version_id 
          
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
        */
        
      END

      /*** FP_AMEND_UTILIZATION 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_UTILIZATION'
        
        DELETE FROM SY_FP_AMEND_UTILIZATION
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null
        
        INSERT  INTO SY_FP_AMEND_UTILIZATION ( 
                MASTER_ID, 
                PLAN_ID, 
                OUT_VERSION_ID, 
                RESOURCE_ID, 
                WORK_DATE, 
                WORK_TIME, 
                RUN_TIME, 
                OFF_TIME, 
                SETUP_TIME, 
                SLACK_TIME, 
                OFF_SETUP_TIME
        )
        SELECT  A.MASTER_ID, 
                A.PLAN_ID, 
                A.OUT_VERSION_ID, 
                --B.ROUTE_ID AS RESOURCE_ID,            -- RESOURCE 설정부분
                A.RESOURCE_ID,                        -- RESOURCE 설정부분
                CONVERT(DATE, A.WORK_DATE)                                AS WORK_DATE, 
                ROUND(AVG(A.WORK_TIME),0)                                 AS WORK_TIME, 
                ROUND(AVG(A.RUN_TIME),0)                                  AS RUN_TIME, 
                ROUND(AVG(A.OFF_TIME),0) + ROUND(AVG(A.OFF_SETUP_TIME),0) AS OFF_TIME, 
                ROUND(AVG(A.SETUP_TIME),0)                                AS SETUP_TIME, 
                ROUND(AVG(A.SLACK_TIME),0)                                AS SLACK_TIME, 
                ROUND(AVG(A.OFF_SETUP_TIME),0)                            AS OFF_SETUP_TIME
        FROM    TH_BUF_OUT_UTILIZATION  A,
                TH_ENG_RESOURCE     B
        WHERE   A.MASTER_ID  = @v_master_id  
        AND     A.PLAN_ID     = @v_plan_id
        AND     A.OUT_VERSION_ID  = @v_out_version_id
        AND     A.MASTER_ID = B.MASTER_ID
        AND     A.PLAN_ID = B.PLAN_ID
        AND     A.RESOURCE_ID = B.RESOURCE_ID
        AND     B.BATCH_TYPE != 'BATCH'
        GROUP  BY A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, A.RESOURCE_ID, A.WORK_DATE        

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        
        INSERT  INTO SY_FP_AMEND_UTILIZATION ( 
                MASTER_ID, 
                PLAN_ID, 
                OUT_VERSION_ID, 
                RESOURCE_ID, 
                WORK_DATE, 
                WORK_TIME, 
                RUN_TIME, 
                OFF_TIME, 
                SETUP_TIME, 
                SLACK_TIME, 
                OFF_SETUP_TIME
        )
        SELECT MASTER_ID, PLAN_ID, OUT_VERSION_ID,
               RESOURCE_ID, PLAN_DATE, 
               86400 AS WORK_TIME,
               SUM(RUN_TIME) AS RUN_TIME,
               SUM(OFF_TIME) AS OFF_TIME,
               SUM(SETUP_TIME) AS SETUP_TIME,
               SUM(SLACK_TIME) AS SLACK_TIME,
               SUM(OFF_SETUP_TIME) AS OFF_SETUP_TIME
        FROM   (
                SELECT MASTER_ID, PLAN_ID, OUT_VERSION_ID,
                       COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID,
                       LINE_ID, OPERATION_ID, WORK_CENTER_ID,
                       RESOURCE_ID, PLAN_DATE, CATEGORY, 
                       CASE WHEN RR = 1 AND CATEGORY = 'RUN' THEN DIFF ELSE 0 END RUN_TIME,
                       CASE WHEN RR = 2 AND CATEGORY = 'OFFTIME' THEN DIFF ELSE 0 END OFF_TIME,
                       CASE WHEN RR = 3 AND CATEGORY = 'SETUP' THEN DIFF ELSE 0 END SETUP_TIME,
                       CASE WHEN RR = 4 AND CATEGORY = 'SLACK' THEN DIFF ELSE 0 END SLACK_TIME,
                       CASE WHEN RR = 5 AND CATEGORY = 'OFF_SETUP' THEN DIFF ELSE 0 END OFF_SETUP_TIME
                FROM   (
                        SELECT A.*,
                               CONVERT(datetime2, dbo.fn_set_work_date2(master_id, plan_id, a.start_time, a.end_time), 112) AS plan_date,
                               DATEDIFF(SECOND, START_TIME, END_TIME) DIFF
                        FROM   (
                                SELECT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID,
                                       A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, A.WORK_CENTER_ID,
                                       A.RESOURCE_ID, 
                                       CASE R WHEN 0   THEN START_TIME ELSE PLAN_DATE END START_TIME,
                                       CASE R WHEN 0   THEN PLAN_DATE
                                              WHEN CNT THEN END_TIME   ELSE DATEADD(DAY, 1, PLAN_DATE) END END_TIME,
                                       A.CATEGORY
                                FROM   (
                                        SELECT A.*, B.*,
                                               COUNT(1) OVER (PARTITION BY RESOURCE_ID, START_TIME, END_TIME, CATEGORY ORDER BY PLAN_DATE) AS SEQ,
                                               COUNT(1) OVER (PARTITION BY RESOURCE_ID, START_TIME, END_TIME, CATEGORY) AS CNT
                                        FROM   (
                                                SELECT DISTINCT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID,
                                                       B.RES_ATTB_11 AS COMPANY_ID,
                                                       B.RES_ATTB_12 AS DIVISION_ID,
                                                       B.RES_ATTB_13 AS SITE_ID,
                                                       B.RES_ATTB_14 AS PLANT_ID,
                                                       B.RES_ATTB_15 AS FACTORY_ID,
                                                       B.RES_ATTB_17 AS LINE_ID,
                                                       B.RES_ATTB_18 AS OPERATION_ID,
                                                       B.RES_ATTB_19 AS WORK_CENTER_ID,
                                                       A.RESOURCE_ID, A.START_TIME, A.END_TIME, A.CATEGORY
                                                FROM   TH_BUF_OUT_RESOURCE_USAGE  A,
                                                       TH_MST_RESOURCE        B,
                                                       TH_ENG_RESOURCE        C
                                                WHERE  A.MASTER_ID = @v_master_id
                                                AND    A.PLAN_ID = @v_plan_id
                                                AND    A.OUT_VERSION_ID = @v_out_version_id
                                                AND    A.MASTER_ID = B.MASTER_ID
                                                AND    A.PLAN_ID = B.PLAN_ID
                                                AND    A.OUT_VERSION_ID = B.PLAN_ID
                                                AND    A.RESOURCE_ID = B.RESOURCE_ID
                                                AND    A.MASTER_ID = C.MASTER_ID
                                                AND    A.PLAN_ID = C.PLAN_ID
                                                AND    A.RESOURCE_ID = C.RESOURCE_ID
                                                AND    C.BATCH_TYPE = 'BATCH'
                                               ) A
                                               INNER JOIN  (
                                                            SELECT DATEADD(DAY, INT-1, PLAN_START_DTTM) AS PLAN_DATE  
                                                            FROM   TH_ENG_PLAN_INFO A,
                                                                   COPYT            B
                                                            WHERE  A.MASTER_ID = @v_master_id
                                                            AND    A.PLAN_ID = @v_plan_id
                                                            AND    A.PLAN_HORIZON >= INT       
                                                           ) B
                                                     ON    A.START_TIME < B.PLAN_DATE
                                                     AND   A.END_TIME   > B.PLAN_DATE
                                      ) A,
                                      (   
                                       SELECT 1 INT, 0 R
                                       UNION  ALL
                                       SELECT INT, INT R 
                                       FROM   COPYT
                                       ) B   
                                WHERE  SEQ = INT
                                UNION  ALL
                                SELECT A.*
                                FROM   (
                                        SELECT DISTINCT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID,
                                               B.RES_ATTB_11 AS COMPANY_ID,
                                               B.RES_ATTB_12 AS DIVISION_ID,
                                               B.RES_ATTB_13 AS SITE_ID,
                                               B.RES_ATTB_14 AS PLANT_ID,
                                               B.RES_ATTB_15 AS FACTORY_ID,
                                               B.RES_ATTB_17 AS LINE_ID,
                                               B.RES_ATTB_18 AS OPERATION_ID,
                                               B.RES_ATTB_19 AS WORK_CENTER_ID,
                                               A.RESOURCE_ID, A.START_TIME, A.END_TIME, A.CATEGORY
                                        FROM   TH_BUF_OUT_RESOURCE_USAGE  A,
                                               TH_MST_RESOURCE        B,
                                               TH_ENG_RESOURCE        C
                                        WHERE  A.MASTER_ID = @v_master_id
                                        AND    A.PLAN_ID = @v_plan_id
                                        AND    A.OUT_VERSION_ID = @v_out_version_id
                                        AND    A.MASTER_ID = B.MASTER_ID
                                        AND    A.PLAN_ID = B.PLAN_ID
                                        AND    A.OUT_VERSION_ID = B.PLAN_ID
                                        AND    A.RESOURCE_ID = B.RESOURCE_ID
                                        AND    A.MASTER_ID = C.MASTER_ID
                                        AND    A.PLAN_ID = C.PLAN_ID
                                        AND    A.RESOURCE_ID = C.RESOURCE_ID
                                        AND    C.BATCH_TYPE = 'BATCH'
                                       ) A
                                       LEFT OUTER JOIN  (
                                                    SELECT DATEADD(DAY, INT-1, PLAN_START_DTTM) AS PLAN_DATE  
                                                    FROM   TH_ENG_PLAN_INFO A,
                                                           COPYT            B
                                                    WHERE  A.MASTER_ID = @v_master_id
                                                    AND    A.PLAN_ID = @v_plan_id
                                                    AND    A.PLAN_HORIZON >= INT       
                                                   ) B
                                             ON    A.START_TIME < B.PLAN_DATE
                                             AND   A.END_TIME   > B.PLAN_DATE
                                WHERE  B.PLAN_DATE IS NULL
                               ) A
                       ) A,
                       (
                        SELECT 1 RR, 'RUN_TIME'       CATEGORY_ID UNION ALL        
                        SELECT 2 RR, 'OFF_TIME'       CATEGORY_ID UNION ALL        
                        SELECT 3 RR, 'SETUP_TIME'     CATEGORY_ID UNION ALL        
                        SELECT 4 RR, 'SLACK_TIME'     CATEGORY_ID UNION ALL        
                        SELECT 5 RR, 'OFF_SETUP_TIME' CATEGORY_ID    
                       ) B
               ) A
        GROUP  BY MASTER_ID, PLAN_ID, OUT_VERSION_ID,
                  RESOURCE_ID, PLAN_DATE

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

      END

      /*** FP_AMEND_PSI 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_PSI'
        
        DELETE FROM SY_FP_AMEND_PSI
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null
        

        SET @v_table_name = 'TH_BUF_SCM_AMEND_PSI_A'

        DELETE FROM TH_BUF_SCM_AMEND_PSI_A
        
        INSERT INTO TH_BUF_SCM_AMEND_PSI_A
        SELECT  A.MASTER_ID, 
                A.PLAN_ID, 
                A.OUT_VERSION_ID, 
                A.SITE_ID ,
                A.ITEM_ID ,
                A.PSI_DATE,
                SUM(A.BOH_QTY) BOH_QTY ,
                SUM(A.IN_QTY) IN_QTY,
                SUM(A.OUT_QTY ) OUT_QTY
        FROM
        (
          SELECT  A.MASTER_ID, 
                  A.PLAN_ID, 
                  A.OUT_VERSION_ID, 
                  A.ITEM_ID ,
                  A.SITE_ID ,
                  CAST(CONVERT(nvarchar, DBO.FN_SET_WORK_DATE2 (A.MASTER_ID, A.PLAN_ID , A.EVENT_TIME, A.EVENT_TIME ), 112) AS DATETIME) AS PSI_DATE,
                  A.BOH_QTY ,
                  A.IN_QTY,
                  A.OUT_QTY
          FROM   (
                  SELECT A.MASTER_ID
                       , A.PLAN_ID
                       , A.PLAN_ID AS OUT_VERSION_ID
                       , A.SITE_ID
                       , A.ITEM_ID
                       , CASE WHEN A.RECEIVING_DTTM < C.PLAN_START_DTTM THEN C.PLAN_START_DTTM
                                                                        ELSE A.RECEIVING_DTTM
                         END  EVENT_TIME
                       , CASE WHEN A.RECEIVING_DTTM < C.PLAN_START_DTTM THEN QTY
                                                                        ELSE 0
                         END  BOH_QTY
                       , CASE WHEN A.RECEIVING_DTTM < C.PLAN_START_DTTM THEN 0
                                                                        ELSE QTY
                         END  IN_QTY
                       , 0 OUT_QTY
                  FROM   TH_MST_STOCK_PLAN A,
                         (
                          SELECT ITEM_ID, SITE_ID, OPERATION_ID
                          FROM   (
                                  SELECT ITEM_ID, SITE_ID, OPERATION_ID,
                                         DENSE_RANK() OVER (PARTITION BY ITEM_ID, SITE_ID ORDER BY OPERATION_SEQ DESC) SEQ
                                  FROM   TH_ENG_ITEM_ROUTE_SITE A
                                  WHERE  A.MASTER_ID = @v_master_id + '_AMEND'
                                  AND    A.PLAN_ID = @v_plan_id
                                 ) A
                          WHERE  SEQ = 1
                         ) B,
                         TH_MST_PLAN C
                  WHERE   A.MASTER_ID = @v_master_id
                  AND     A.PLAN_ID = @v_plan_id
                  AND    A.ITEM_ID = B.ITEM_ID
                  AND    A.SITE_ID = B.SITE_ID
                  AND    A.OPERATION_ID = B.OPERATION_ID
                  AND    A.MASTER_ID = C.MASTER_ID
                  AND    A.PLAN_ID = C.PLAN_ID
                 ) A
          UNION ALL
          -- 생산완료 공정 이후 투입 수량
          SELECT  A.MASTER_ID, 
                  A.PLAN_ID, 
                  A.OUT_VERSION_ID, 
                  A.ITEM_ID ,
                  A.SITE_ID ,
                  CAST(CONVERT(nvarchar, DBO.FN_SET_WORK_DATE2 (A.MASTER_ID, A.PLAN_ID , A.EVENT_TIME, A.EVENT_TIME ), 112) AS DATETIME) AS PSI_DATE,
                  A.BOH_QTY ,
                  A.IN_QTY,
                  A.OUT_QTY
          FROM   (
                  SELECT A.MASTER_ID,
                         A.PLAN_ID,
                         A.OUT_VERSION_ID,
                         A.ITEM_ID,
                         A.SITE_ID,
                         A.EVENT_TIME,
                         0 AS BOH_QTY,
                         0 AS IN_QTY,
                         ABS(A.PSI_QTY) AS OUT_QTY
                  FROM   (
                          SELECT DISTINCT 
                                 A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, A.ITEM_ID, A.EVENT_TIME, A.EVENT_QTY, B.EVENT_QTY AS PSI_QTY,
                                 A.WORK_ORDER_ID, A.ITEM_PEGGING_ID, A.SITE_ID,
                                 C.WORK_ORDER_ID AS FROM_WORK_ORDER_ID
                          FROM   TH_BUF_OUT_ITEM_PLAN A
                                 INNER HASH JOIN TH_BUF_OUT_ITEM_PEGGING B
                                        ON     A.MASTER_ID = B.MASTER_ID
                                        AND    A.PLAN_ID = B.PLAN_ID
                                        AND    A.OUT_VERSION_ID = B.OUT_VERSION_ID
                                        AND    A.ITEM_PEGGING_ID = B.OUT_ITEM_PEGGING_ID
                                 INNER HASH JOIN TH_BUF_OUT_ITEM_PEGGING C
                                        ON     A.MASTER_ID = C.MASTER_ID
                                        AND    A.PLAN_ID = C.PLAN_ID
                                        AND    A.OUT_VERSION_ID = C.OUT_VERSION_ID
                                        AND    B.IN_ITEM_PEGGING_ID = C.OUT_ITEM_PEGGING_ID
                          WHERE  A.MASTER_ID = @V_MASTER_ID
                          AND    A.PLAN_ID = @V_PLAN_ID
                          AND    A.OUT_VERSION_ID = @V_OUT_VERSION_ID
                          AND    A.WORK_ORDER_ID IS NOT NULL
                          AND    A.EVENT_QTY < 0
                         ) A
                         INNER HASH JOIN TH_BUF_OUT_WORK_ORDER B
                                ON     A.MASTER_ID = B.MASTER_ID
                                AND    A.PLAN_ID = B.PLAN_ID
                                AND    A.FROM_WORK_ORDER_ID = B.WORK_ORDER_ID
                         INNER HASH JOIN (
                                          SELECT ITEM_ID, SITE_ID, OPERATION_ID
                                          FROM   (
                                                  SELECT ITEM_ID, SITE_ID, OPERATION_ID,
                                                         DENSE_RANK() OVER (PARTITION BY ITEM_ID, SITE_ID ORDER BY OPERATION_SEQ DESC) SEQ
                                                  FROM   TH_ENG_ITEM_ROUTE_SITE
                                                  WHERE  MASTER_ID = @V_MASTER_ID
                                                  AND    PLAN_ID = @V_PLAN_ID + '_AMEND'
                                                 ) A
                                          WHERE  SEQ = 1
                                         ) D
                                ON     B.ITEM_ID = D.ITEM_ID
                                AND    B.SITE_ID = D.SITE_ID
                                AND    B.OPERATION_ID = D.OPERATION_ID
                 ) A
          UNION ALL
          -- 생산공정 생산완료 투입
          SELECT  A.MASTER_ID, 
                  A.PLAN_ID, 
                  A.OUT_VERSION_ID, 
                  A.ITEM_ID ,
                  A.SITE_ID ,
                  CAST(CONVERT(nvarchar, DBO.FN_SET_WORK_DATE2 (A.MASTER_ID, A.PLAN_ID , A.EVENT_TIME, A.EVENT_TIME ), 112) AS DATETIME) AS PSI_DATE,
                  A.BOH_QTY ,
                  A.IN_QTY,
                  A.OUT_QTY
          FROM   (
                  SELECT A.MASTER_ID,
                         A.PLAN_ID,
                         A.OUT_VERSION_ID,
                         A.ITEM_ID,
                         A.SITE_ID,
                         A.START_TIME AS EVENT_TIME,
                         0 AS BOH_QTY,
                         ABS(A.COMPLETE_QTY) AS IN_QTY,
                         0 AS OUT_QTY
                  FROM   TH_BUF_OUT_WORK_ORDER_SPL A,
                         (
                          SELECT ITEM_ID, SITE_ID, OPERATION_ID
                          FROM   (
                                  SELECT ITEM_ID, SITE_ID, OPERATION_ID,
                                         DENSE_RANK() OVER (PARTITION BY ITEM_ID, SITE_ID ORDER BY OPERATION_SEQ DESC) SEQ
                                  FROM   TH_ENG_ITEM_ROUTE_SITE
                                  WHERE  MASTER_ID = @V_MASTER_ID
                                  AND    PLAN_ID = @V_PLAN_ID + '_AMEND'
                                 ) A
                          WHERE  SEQ = 1
                         ) B      
                  WHERE  A.MASTER_ID = @V_MASTER_ID
                  AND    A.PLAN_ID = @V_PLAN_ID
                  AND    A.OUT_VERSION_ID = @V_OUT_VERSION_ID
                  AND    A.ITEM_ID = B.ITEM_ID
                  AND    A.SITE_ID = B.SITE_ID
                  AND    A.OPERATION_ID = B.OPERATION_ID
                 ) A
          UNION ALL
          -- 완성 공정 출하
          SELECT  A.MASTER_ID, 
                  A.PLAN_ID, 
                  A.OUT_VERSION_ID, 
                  A.ITEM_ID ,
                  A.SITE_ID ,
                  CAST(CONVERT(nvarchar, DBO.FN_SET_WORK_DATE2 (A.MASTER_ID, A.PLAN_ID , A.EVENT_TIME, A.EVENT_TIME ), 112) AS DATETIME) AS PSI_DATE,
                  A.BOH_QTY ,
                  A.IN_QTY,
                  A.OUT_QTY
          FROM   (
                  SELECT A.MASTER_ID,
                         A.PLAN_ID,
                         A.OUT_VERSION_ID,
                         A.OPERATION_ID,
                         A.OUT_ITEM_ID AS ITEM_ID,
                         A.SITE_ID,
                         CASE WHEN A.LPST > A.EVENT_TIME THEN DATEADD(SECOND, -1, A.LPST)
                                                         ELSE DATEADD(SECOND, -1, A.EVENT_TIME)
                         END  AS EVENT_TIME,
                         0 AS BOH_QTY,
                         0 AS IN_QTY,
                         ABS(A.EVENT_QTY) AS OUT_QTY
                  FROM   (             
                          SELECT DISTINCT 
                                 A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID,
                                 C.EVENT_QTY, B.OUT_ITEM_PEGGING_ID, B.OUT_ITEM_ID, B.SITE_ID, B.OPERATION_ID, B.LPST, C.EVENT_TIME
                          FROM   TH_BUF_OUT_ITEM_PEGGING A
                                 INNER HASH JOIN TH_BUF_OUT_ORDER_TRACKING B
                                        ON     A.MASTER_ID = B.MASTER_ID
                                        AND    A.PLAN_ID = B.PLAN_ID
                                        AND    A.OUT_VERSION_ID = B.OUT_VERSION_ID
                                        AND    A.IN_ITEM_PEGGING_ID = B.OUT_ITEM_PEGGING_ID
                                 INNER HASH JOIN TH_BUF_OUT_ITEM_PLAN_SPL C
                                        ON     A.MASTER_ID = C.MASTER_ID
                                        AND    A.PLAN_ID = C.PLAN_ID
                                        AND    A.OUT_VERSION_ID = C.OUT_VERSION_ID
                                        AND    A.IN_ITEM_PEGGING_ID = C.ORG_ITEM_PEGGING_ID
                                 INNER HASH JOIN TH_ENG_NET_DEMAND D
                                        ON     A.MASTER_ID = D.MASTER_ID
                                        AND    A.PLAN_ID = D.PLAN_ID
                                        AND    A.DEMAND_ID = D.DEMAND_ID
                                 INNER HASH JOIN (
                                                  SELECT ITEM_ID, SITE_ID, OPERATION_ID
                                                  FROM   (
                                                          SELECT ITEM_ID, SITE_ID, OPERATION_ID,
                                                                 DENSE_RANK() OVER (PARTITION BY ITEM_ID, SITE_ID ORDER BY OPERATION_SEQ DESC) SEQ
                                                          FROM   TH_ENG_ITEM_ROUTE_SITE
                                                          WHERE  MASTER_ID = @V_MASTER_ID
                                                          AND    PLAN_ID = @V_PLAN_ID + '_AMEND'
                                                         ) A
                                                  WHERE  SEQ = 1
                                                 ) E
                                        ON     B.OUT_ITEM_ID = E.ITEM_ID
                                        AND    B.SITE_ID = E.SITE_ID
                                        AND    B.OPERATION_ID = E.OPERATION_ID
                          WHERE  A.MASTER_ID = @V_MASTER_ID
                          AND    A.PLAN_ID = @V_PLAN_ID
                          AND    A.OUT_VERSION_ID = @V_OUT_VERSION_ID
                          AND    A.DEMAND_ID IS NOT NULL
                         ) A
                 ) A        
        ) A
        GROUP BY  A.MASTER_ID, 
                  A.PLAN_ID, 
                  A.OUT_VERSION_ID, 
                  A.ITEM_ID ,
                  A.SITE_ID ,
                  A.PSI_DATE

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        SET @v_table_name = 'TH_BUF_SCM_AMEND_PSI_B'

        DELETE FROM TH_BUF_SCM_AMEND_PSI_B
        
        INSERT INTO TH_BUF_SCM_AMEND_PSI_B
        SELECT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, A.SITE_ID, A.ITEM_ID, A.PSI_DATE,
               CASE WHEN B.BOH_QTY IS NULL THEN 0 ELSE B.BOH_QTY END AS BOH_QTY,
               CASE WHEN B.IN_QTY  IS NULL THEN 0 ELSE B.IN_QTY  END AS IN_QTY,
               CASE WHEN B.OUT_QTY IS NULL THEN 0 ELSE B.OUT_QTY END AS OUT_QTY
        FROM   (
                SELECT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, A.SITE_ID, A.ITEM_ID, B.PSI_DATE
                FROM   (
                        SELECT MASTER_ID, PLAN_ID, OUT_VERSION_ID, SITE_ID, ITEM_ID
                        FROM   TH_BUF_SCM_AMEND_PSI_A
                        GROUP  BY MASTER_ID, PLAN_ID, OUT_VERSION_ID, SITE_ID, ITEM_ID
                       ) A,
                       (
                        SELECT A.MASTER_ID, A.PLAN_ID,
                               CONVERT(DATE, DATEADD(DD, INT-1, PLAN_START_DTTM)) AS PSI_DATE 
                        FROM   TH_ENG_PLAN_INFO A,
                               COPYT            B
                        WHERE  A.MASTER_ID = @v_master_id
                        AND    A.PLAN_ID = @v_plan_id
                        AND    B.INT <= DEMAND_HORIZON + 7
                       ) B
                WHERE  A.MASTER_ID = B.MASTER_ID
                AND    A.PLAN_ID = B.PLAN_ID
               ) A
               LEFT OUTER JOIN TH_BUF_SCM_AMEND_PSI_A B
                    ON    A.MASTER_ID = B.MASTER_ID
                    AND   A.PLAN_ID = B.PLAN_ID
                    AND   A.OUT_VERSION_ID = B.OUT_VERSION_ID
                    AND   A.SITE_ID = B.SITE_ID
                    AND   A.ITEM_ID = B.ITEM_ID
                    AND   A.PSI_DATE = B.PSI_DATE

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        SET @v_table_name = 'TH_BUF_SCM_AMEND_PSI_C'

        DELETE FROM TH_BUF_SCM_AMEND_PSI_C
        
        INSERT INTO TH_BUF_SCM_AMEND_PSI_C
        SELECT
                A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID ,  
                A.SITE_ID, A.ITEM_ID, A.PSI_DATE, 
                MAX(A.BOH_QTY) AS BOH_QTY, MAX(A.IN_QTY) AS IN_QTY, MAX(A.OUT_QTY) AS OUT_QTY,
                SUM(B.BOH_QTY) AS CUM_BOH_QTY,
                SUM(B.IN_QTY) AS CUM_IN_QTY,
                SUM(B.OUT_QTY) AS CUM_OUT_QTY,
                A.ROWNUM AS R
        FROM
        (
          SELECT  A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID,  
                  A.SITE_ID, A.ITEM_ID, A.PSI_DATE, A.BOH_QTY, A.IN_QTY, A.OUT_QTY,
                  DENSE_RANK() OVER(PARTITION BY SITE_ID,ITEM_ID ORDER BY PSI_DATE) AS ROWNUM
          FROM    TH_BUF_SCM_AMEND_PSI_B A 
          WHERE   1=1
        ) A
        INNER JOIN 
        (
          SELECT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID ,  
              A.SITE_ID, A.ITEM_ID, A.PSI_DATE, A.BOH_QTY, A.IN_QTY, A.OUT_QTY,
              DENSE_RANK() OVER(PARTITION BY SITE_ID,ITEM_ID ORDER BY PSI_DATE) AS ROWNUM
          FROM   TH_BUF_SCM_AMEND_PSI_B A 
          WHERE 1=1
        ) B 
        ON A.ROWNUM >= B.ROWNUM AND A.MASTER_ID=B.MASTER_ID AND A.PLAN_ID=B.PLAN_ID AND A.OUT_VERSION_ID=B.OUT_VERSION_ID AND A.SITE_ID=B.SITE_ID AND A.ITEM_ID=B.ITEM_ID
        GROUP BY A.ROWNUM, A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, A.SITE_ID, A.ITEM_ID, A.PSI_DATE

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


        SET @v_table_name = 'TH_BUF_SCM_AMEND_PSI_D'

        DELETE FROM TH_BUF_SCM_AMEND_PSI_D
        
        INSERT INTO TH_BUF_SCM_AMEND_PSI_D
        SELECT A.MASTER_ID, A.PLAN_ID,  A.OUT_VERSION_ID , ISNULL(A.SITE_ID,'-') SITE_ID, A.ITEM_ID, A.PSI_DATE AS PSI_DATE,
               CASE WHEN B.SITE_ID IS NULL THEN A.BOH_QTY ELSE (B.CUM_BOH_QTY+B.CUM_IN_QTY-B.CUM_OUT_QTY) END AS BOH_QTY,
               A.IN_QTY, A.OUT_QTY, (A.CUM_BOH_QTY+A.CUM_IN_QTY-A.CUM_OUT_QTY) AS EOH_QTY 
        FROM   TH_BUF_SCM_AMEND_PSI_C A
            LEFT OUTER JOIN TH_BUF_SCM_AMEND_PSI_C B
                 ON A.MASTER_ID = B.MASTER_ID AND A.PLAN_ID = B.PLAN_ID AND A.SITE_ID = B.SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.R= B.R + 1 
        WHERE  1=1

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

        SET @v_table_name = 'FP_AMEND_PSI'

        INSERT  INTO SY_FP_AMEND_PSI ( 
                MASTER_ID, 
                PLAN_ID, 
                OUT_VERSION_ID, 
                ITEM_ID, 
                SITE_ID, 
      --                    ROUTE_ID, 
      --                    OPERATION_ID, 
                PSI_DATE, 
                CATEGORY, 
                CATEGORY_SEQ, 
                QTY
        )
        SELECT  MASTER_ID ,
                PLAN_ID ,
                OUT_VERSION_ID ,
                ITEM_ID , 
                SITE_ID ,
                PSI_DATE , 
                'BOH' CATEGORY ,
                1 CATEGORY_SEQ ,
                BOH_QTY 
        FROM    TH_BUF_SCM_AMEND_PSI_D
        UNION ALL
        SELECT  MASTER_ID ,
                PLAN_ID ,
                OUT_VERSION_ID ,
                ITEM_ID , 
                SITE_ID ,
                PSI_DATE , 
                'IN' CATEGORY ,
                2 CATEGORY_SEQ ,
                IN_QTY 
        FROM    TH_BUF_SCM_AMEND_PSI_D
        UNION ALL
        SELECT  MASTER_ID ,
                PLAN_ID ,
                OUT_VERSION_ID ,
                ITEM_ID , 
                SITE_ID ,
                PSI_DATE , 
                'OUT' CATEGORY ,
                3 CATEGORY_SEQ ,
                OUT_QTY 
        FROM    TH_BUF_SCM_AMEND_PSI_D
        UNION ALL
        SELECT  MASTER_ID ,
                PLAN_ID ,
                OUT_VERSION_ID ,
                ITEM_ID , 
                SITE_ID ,
                PSI_DATE , 
                'EOH' CATEGORY ,
                4 CATEGORY_SEQ ,
                EOH_QTY 
        FROM    TH_BUF_SCM_AMEND_PSI_D
      
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null

      END

      /*** FP_AMEND_RESOURCE_USAGE 생성 ***/
      BEGIN
        
        SET @v_table_name = 'FP_AMEND_RESOURCE_USAGE'
        
        DELETE FROM SY_FP_AMEND_RESOURCE_USAGE
        WHERE  MASTER_ID = @v_master_id
        AND    PLAN_ID = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null


        INSERT INTO SY_FP_AMEND_RESOURCE_USAGE
        SELECT
                A.MASTER_ID
              , A.PLAN_ID
              , A.OUT_VERSION_ID
              , A.USAGE_SEQ
              , A.RESOURCE_ID
              , A.START_TIME
              , CASE WHEN A.END_TIME > @v_plan_end_date THEN @v_plan_end_date
                                                        ELSE A.END_TIME 
                END  AS END_TIME
              , A.CATEGORY
              , A.COMPLETE_QTY
              , A.RESOURCE_GROUP_ID
              , A.ITEM_ID
              , A.SITE_ID
              , A.ROUTE_ID
              , ISNULL(B.WORK_ORDER_ID, A.WORK_ORDER_ID) AS WORK_ORDER_ID
              , A.SETUP_FLAG        
        FROM    TH_BUF_OUT_RESOURCE_USAGE A
                LEFT OUTER JOIN TH_MST_SCM_FIX_WORK_SPLIT B
                     ON    A.MASTER_ID      = B.MASTER_ID
                     AND   A.PLAN_ID        = B.PLAN_ID
                     AND   A.WORK_ORDER_ID  = B.SPLIT_WORK_ORDER_ID
        WHERE   A.MASTER_ID  = @v_master_id  
        AND     A.PLAN_ID     = @v_plan_id
        AND     A.OUT_VERSION_ID  = @v_out_version_id
        AND     A.START_TIME < @v_plan_end_date

        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
        
        /* PR_SCM_OF_AMEND_ADJUST 로 이관         
        UPDATE  SY_FP_AMEND_RESOURCE_USAGE
        SET     WORK_ORDER_ID = B.PLAN_ORDER_ID
        FROM    SY_FP_AMEND_RESOURCE_USAGE A
                ,TH_EXP_PLANORDER B 
        WHERE   A.MASTER_ID         = B.MASTER_ID 
        AND     A.PLAN_ID           = B.PLAN_ID 
        AND     A.WORK_ORDER_ID     = B.ORDER_ID
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
          
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
        */
        
      END

    /* PR_SCM_OF_AMEND_ADJUST 로 이관         
      /*** FP_AMEND_PRODUCTION_PLAN_R 생성 ***/
    */


      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', 999999, null, '=============== End of procedure ===============', null

      
